    # The 8 marks the centre; each isolated non-7 colour specifies the
    # Chebyshev-distance ring on which it is placed.
    cr=cc=None
    for r in range(h):
        for c in range(w):
            if grid[r][c]==8:
                cr,cc=r,c
                break
        if cr is not None: break
    rings={}
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v not in (7,8):
                d=max(abs(r-cr),abs(c-cc))
                rings[d]=v
    out=[[7 for _ in range(w)] for _ in range(h)]
    for r in range(h):
        for c in range(w):
            d=max(abs(r-cr),abs(c-cc))
            if d==0: out[r][c]=8
            elif d in rings: out[r][c]=rings[d]
    return out"}

